blocks.mermaid:
flowchart TD
  A["¿Sobre qué preguntas?"] --> B{"¿Una persona o una cosa?"}
  B -- "Persona" --> C{"¿Quién es o de quién es algo?"}
  C -- "quién" --> D["who: Who is that man?"]
  C -- "de quién" --> E["whose: Whose is this hat?"]
  B -- "Cosa" --> F{"¿Eliges entre unas pocas opciones?"}
  F -- "Sí" --> G["which: Which is your room?"]
  F -- "No, pides un dato abierto" --> H["what: What is your name?"]

flowchart TD
  A["¿Cuánto? ¿Cuántos?"] --> B{"¿Preguntas un precio?"}
  B -- "Sí" --> C["how much: How much is this hat?"]
  B -- "No" --> D{"¿Se puede contar? (uno, dos, tres…)"}
  D -- "Sí: sustantivo en plural" --> E["how many: How many brothers do you have?"]
  D -- "No: incontable" --> F["how much: How much money do you have?"]
